(1184, 4987176600554, 0, 'Vicks Vaporub 10 g', 0, 0, 0, 'POT', 'POT', 1, 'OTC', 7067, 0, 7844, 0, 10000, 9412, 8236, 0, '', '<p>Obat gosok untuk meringankan gejala pilek dan batuk karena flu Komposisi setiap kemasan 10gr mengandung: camphor 526mg, menthol 282mg dan eucalyptus oil 133mg</p>\r\n', '<p>a</p>\r\n', '', '0000-00-00 00:00:00', 22, 0, 0, 22, '', 'inactive', NULL, 'standar', NULL, ''),
(1185, 8994554001045, 0, 'Oxycan Green 500 cc Kaleng', 0, 0, 0, 'Botol', 'Kaleng', 1, 'OTC', 36364, 0, 36328, 0, 64000, 43590, 38144, 0, '', '<p>Memenuhi kebutuhan oksigen dan membantu mengembalikan kadar oksigen dalam tubuh seperti keadaan normal. Komposisi Oxygen</p>\r\n', '<p>a</p>\r\n', '', '0000-00-00 00:00:00', 5, 0, 0, 5, '', 'inactive', NULL, 'standar', NULL, ''),
