(2936, 8997037214321, 0, 'Ringer Lactate 500 ml Widatra', 0, 1, 0, 'Fls', '', 1, 'OTC', 0, 0, 8498, 0, 11000, 10197, 8923, 0, '', '<p>Ringer laktat adalah cairan infus&nbsp;yang biasa digunakan pada pasien dewasa dan anak-anak sebagai sumber elektrolit dan air.</p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(2937, 200537, 0, 'Kolkatriol 0.25 mcg 30 Kapsul', 0, 0, 0, 'Botol', '', 1, 'OTC', 0, 0, 199204, 0, 249000, 239025, 209164, 0, '', '<p>Osteoporosis paska menopause, Osteodistrofi Ginjal pada Gagal Ginjal Khronis, Rakhitis akibat defisiensi vit.D, Hipoparatiroidisme paska operasi &amp; Idiopatik, Pseudo-Hipoparatiroidisme.</p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
