(3088, 8997007270074, 0, 'Tissue Magic Power Hitam 6 Lembar', 0, 0, 0, 'Box', 'Box', 1, 'OTC', 14415, 0, 10800, 0, 18000, 12959, 11340, 0, '', '<p>TISSUE MAGIC POWER merupakan tissue herbal antiseptik yang dapat digunakan untuk membersihkan, mencegah bakteri, meningkatkan kekuatan dalam berhubungan, serta mencegah ejakulasi dini.</p>\r\n\r\n<p>Indikasi Umum</p>\r\n\r\n<p>Membersihkan, mencegah bakteri, meningkatkan kekuatan dalam berhubungan, serta mencegah ejakulasi dini.</p>\r\n', '', '', '0000-00-00 00:00:00', 1, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(3089, 8997223540241, 0, 'Tissue Lovers for Man 6 Sachet', 0, 0, 0, 'Box', 'Box', 1, 'OTC', 10000, 0, 8880, 0, 13500, 10655, 9324, 0, '', '<p>TISSUE LOVERS FOR MAN merupakan tisu basah menyegarkan dan membersihkan kulit daerah sensitif dengan efektif.</p>\r\n\r\n<p>Indikasi Umum</p>\r\n\r\n<p>Produk ini digunakan untuk menyegarkan dan membersihkan kulit daerah sensitif dengan efektif.</p>\r\n\r\n<p>&nbsp;</p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 6, '', 'inactive', NULL, 'standar', NULL, ''),
