(3121, 8997204770391, 0, 'Cheesethins Cookies 80 g', 0, 0, 0, 'Pcs', '', 1, 'OTC', 0, 0, 26030, 0, 30000, 31233, 27332, 0, '', '<p>heesethins, kukis krispi tanpa terigu terbuat dari tepung &quot;Ladang Lima&quot;, tepung berbahan singkong yang tumbuh di Indonesia, dipadu dengan taburan almond, keju, dan serpihan kelapa yang memberikan rasa gurih dan renyah, menjadikan Cheesethins sebagai pilihan kukis lezat bebas gluten yang lebih sehat dan bikin hari-hari ngemilmu makin seru. Bebas gluten, tanpa tambahan telur, tanpa pengawet, tanpa tambahan MSG.</p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(3122, 200565, 0, 'Elkana 10 Tablet', 0, 0, 0, 'Strip', 'Box', 10, 'OTC', 87500, 0, 9615, 0, 12000, 11537, 10096, 0, '', '<p>ELKANA merupakan tablet dengan kandungan multivitamin dan mineral yang berfungsi sebagai pelengkap selama masa kehamilan, menyusui dan pertumbuhan.</p>\r\n\r\n<p>&nbsp;</p>\r\n', '', '', '0000-00-00 00:00:00', 1, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
