(3884, 200796, 0, 'Asam Mefenamat 500 mg 10 Kaplet Mersi', 0, 0, 0, 'Blister', '', 1, 'OTC', 2100, 0, 1981, 0, 4000, 2377, 2080, 0, '', '<p><span style=\"background-color:rgb(249, 249, 249); font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">Meredakan nyeri ringan hingga sedang pada sakit kepala, sakit gigi, nyeri haid primer, termasuk nyeri karena trauma, nyeri otot, dan nyeri paska operasi</span></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(3885, 200797, 0, 'Lameson 8 mg 10 Tablet', 0, 0, 0, 'Blister', '', 1, 'OTC', 70000, 0, 75758, 0, 97000, 90902, 79546, 0, '', '<p><span style=\"color:rgb(83, 86, 90); font-family:inter,sans-serif; font-size:14px\">LAMESON 8 merupakan obat dengan kandungan Methylprednisolon yang merupakan obat golongan glukokortikoid turunan prednisolon yang mempunyai efek kerja dengan cara mengikat dan mengaktifkan reseptor glukokortikoid intraseluler, reseptor glukokortikoid yang diaktifkan berikatan dengan daerah promotor DNA (yang dapat mengaktifkan atau menekan transkripsi) dan mengaktifkan faktor transkripsi yang mengakibatkan inaktivasi gen melalui deasetilasi histon. Obat ini diindikasikan untuk keadaan alergi dan mengurangi peradangan atau supresi inflamasi.&nbsp;</span></p>\r\n', '', '', '0000-00-00 00:00:00', 2, 0, 0, 2, '', 'inactive', NULL, 'standar', NULL, ''),
