(3896, 8992821100422, 0, 'Acnes UV Tint 30 g', 0, 0, 0, 'Fls', 'Tube', 1, 'OTC', 49500, 0, 32967, 0, 67000, 39557, 34615, 0, '', '<p><span style=\"color:rgb(33, 33, 33); font-family:open sauce one,sans-serif; font-size:14px\">Acnes UV Tint Natural Green</span><br />\r\n<span style=\"color:rgb(33, 33, 33); font-family:open sauce one,sans-serif; font-size:14px\">Merupakan lotion yang mengandung SPF-35 dan PA+++ untuk melindungi kulit dari sinar matahari yang dapat memperparah jerawat.</span><br />\r\n<span style=\"color:rgb(33, 33, 33); font-family:open sauce one,sans-serif; font-size:14px\">Dengan warna hijau membantu mengurangi rona kemerahan pada wajah akibat jerawat, dapat digunakan sebagai alas bedak.</span><br />\r\n<span style=\"color:rgb(33, 33, 33); font-family:open sauce one,sans-serif; font-size:14px\">Antibakteri untuk melawan bakteri penyebab jerawat.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(3897, 200803, 0, 'Imboost Effervescent Rasa Anggur 8 Tablet', 0, 0, 0, 'Box', 'Tube', 1, 'OTC', 33600, 0, 35804, 0, 45000, 42961, 37594, 0, '', '<p><span style=\"color:rgb(83, 86, 90); font-family:inter,sans-serif; font-size:14px\">IMBOOST EFFERVESCENT RASA ANGGUR merupakan produk suplemen kesehatan yang mengandung Echinacea purpure Herba Dry Juice Concentrate, Zinc Picolinate, dan Vitamin C yang digunakan untuk membantu memelihara daya tahan tubuh.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 1, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(3898, 200804, 0, 'Ramipril 10 mg 10 Kaplet Dexa', 0, 0, 0, 'Strip', '', 1, 'OTC', 9050, 0, 10046, 0, 12500, 12054, 10548, 0, '', '<p><span style=\"color:rgb(83, 86, 90); font-family:inter,sans-serif; font-size:14px\">RAMIPRIL 10 MG KAPLET adalah obat yang digunakan untuk mengobati hipertensi (tekanan darah tinggi), nefropati diabetik, dan beberapa jenis gagal jantung kronis. Obat ini adalah obat anti hipertensi yang termasuk angiotensin converting enzyme (ACE) inhibitor generasi kedua.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 5, 0, 0, 5, '', 'inactive', NULL, 'standar', NULL, ''),
