(4125, 200887, 0, 'Broadamox 500 mg 10 Kaplet', 0, 0, 0, 'Strip', 'Box', 10, 'OTC', 50046, 0, 5555, 0, 15000, 6665, 5833, 0, '', '<p><span style=\"color:rgb(83, 83, 83); font-family:gothamrounded,sans-serif; font-size:12px\">Broadamox mengandung amoxycillin trihydrate 500 mg yang berfungsi untuk mengobati infeksi saluran kemih, infeksi saluran nafas atas dan bawah, infeksi kulit dan jaringan lunak, mencegah endokarditis dan eradikasi Helicobacter pylori.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 4, 0, 0, 4, '', 'inactive', NULL, 'standar', NULL, ''),
(4126, 8993514112050, 0, 'Pimtrakol Fitotorant Sirup 60 ml ', 0, 0, 0, 'Botol', '', 1, 'OTC', 15563.96, 0, 12887, 0, 21000, 15463, 13531, 0, '', '<p>Membantu meredakan batuk berdahak.</p>\r\n', '', '', '0000-00-00 00:00:00', 1, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(4127, 8993514112043, 0, 'Pim-Tra-Kol Fitotusive Sirup 60 ml', 0, 0, 0, 'Botol', '', 1, 'OTC', 16700, 0, 14829, 0, 23000, 17793, 15570, 0, '', '<p>Meredakan batuk kering dan melegakan tenggorokan.</p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(4128, 200888, 0, 'Betahistine Mesilate 6 mg 6 Tablet Dexa', 0, 0, 0, 'Strip', 'Box', 10, 'OTC', 83916, 0, 2888, 0, 12000, 3465, 3032, 0, '', '<p><span style=\"background-color:rgb(249, 249, 249); font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">BETAHISTIN 6 MG TABLET merupakan obat generik dengan kandungan Betahistine Mesylate. Betahistine adalah suatu analog histamin dan dapat mengurangi tekanan endolimfatik dengan cara memperbaiki mikrosirkulasi. Obat ini digunakan untuk mengobati vertigo, tinitus dan gangguan pendengaran yang terkait dengan penyakit meniere.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
