(4131, 200889, 0, 'Gentamicin Krim 0.1% 5 g Molex', 0, 0, 0, 'Tube', 'Tube', 1, 'OTC', 3000, 0, 3330, 0, 6000, 3996, 3497, 0, '', '<p><span style=\"font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">Mengobati infeksi pada kulit yang disebabkan oleh bakteri, dengan cara mengganggu sintesis protein bakteri dengan mengikat subunit ribosom 30S yang menghasilkan membran sel bakteri yang rusak</span></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(4132, 200890, 0, 'Albumin Fit 60 Kapsul', 0, 0, 0, 'Botol', '', 1, 'OTC', 0, 0, 13500, 0, 25000, 16199, 14175, 0, '', '<p>Membantu meningkatkan daya tahan tubuh , mempercepat penyembuhan luka luar atau dalam.</p>\r\n', '', '', '0000-00-00 00:00:00', 4, 0, 0, 4, '', 'inactive', NULL, 'standar', NULL, ''),
(4133, 8992821103508, 0, 'Acnes Derma Care Gentle Cleanser 120 g', 0, 0, 0, 'Botol', 'Botol', 1, 'OTC', 55800, 0, 37163, 0, 77000, 44592, 39021, 0, '', '<p><span style=\"color:rgb(104, 116, 128); font-family:roboto; font-size:16px\">Acnes Derma Care Gentle Cleanser merupakan pembersih wajah lembut dengan formula non-soap yang mengandung Salicylic Acid untuk merawat kulit berjerawat, Vitamin C sebagai antioksidan dan mencerahkan kulit, dan Hydrolize Royal Jelly Protein untuk mengurangi resiko iritasi pada kulit.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(4134, 200900, 0, 'Betahistine Mesilate 6 mg 10 Tablet Pyridam', 0, 0, 0, 'Strip', 'Box', 10, 'OTC', 16842, 0, 1869, 0, 15000, 2243, 1962, 0, '', '<p><span style=\"font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">BETAHISTIN 6 MG TABLET merupakan obat generik dengan kandungan Betahistine Mesylate. Betahistine adalah suatu analog histamin dan dapat mengurangi tekanan endolimfatik dengan cara memperbaiki mikrosirkulasi. Obat ini digunakan untuk mengobati vertigo, tinitus dan gangguan pendengaran yang terkait dengan penyakit meniere</span></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(4135, 8992832604063, 0, 'Cassablanca Body Spray Tosca 100 ml', 0, 0, 0, 'Botol', '', 1, 'OTC', 0, 0, 14600, 0, 18000, 17519, 15330, 0, '', '', '', '', '0000-00-00 00:00:00', 1, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(4136, 8993586106056, 0, 'Baby Safe Cotton Buds Small Tip Pot 50s', 0, 0, 0, 'POT', '', 1, 'OTC', 0, 0, 5000, 0, 7000, 6000, 5250, 0, '', '', '', '', '0000-00-00 00:00:00', 2, 0, 0, 2, '', 'inactive', NULL, 'standar', NULL, ''),
(4137, 8993586106063, 0, 'Baby Safe Cotton Buds Regular Tip 50s', 0, 0, 0, 'Sach', '', 1, 'OTC', 0, 0, 2700, 0, 4000, 3240, 2835, 0, '', '', '', '', '0000-00-00 00:00:00', 2, 0, 0, 5, '', 'inactive', NULL, 'standar', NULL, ''),
(4138, 200901, 0, 'Aciclovir 400 mg 10 Tablet Yarindo', 0, 0, 0, 'Strip', '', 1, 'OTC', 4800, 0, 5195, 0, 12000, 6233, 5455, 0, '', '<p><span style=\"background-color:rgb(249, 249, 249); font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">&nbsp;Pengobatan infeksi herpes simpleks pada kulit &amp; membran mukosa, termasuk herpes genital awal &amp; rekuren. Pencegahan infeksi herpes simpleks berulang pada pasien imunokompeten. Profilaksis herpes simpleks pada pasien immunocompromised. Pengobatan herpes zoster.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(4140, 200902, 0, 'Domperidone 10 mg 10 Tablet Sampharindo	', 0, 0, 0, 'Strip', '', 1, 'OTC', 1701.982, 0, 1000, 0, 5000, 1200, 1050, 0, '', '<p><span style=\"background-color:rgb(249, 249, 249); font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">Domperidone merupakan merupakan obat golongan antiemetik yang bekerja dengan cara menghambat reseptor dopamin perifer shg meningkatkan peristaltik esofagus, menurunkan tekanan sfingter esofagus, motilitas dan peristaltik lambung, dan meningkatkan koordinasi gastroduodenal, sehingga memfasilitasi pengosongan lambung dan mengurangi waktu transit usus halus.&nbsp;</span></p>\r\n', '', '', '0000-00-00 00:00:00', 2, 0, 0, 3, '', 'inactive', NULL, 'standar', NULL, ''),
(4141, 200903, 0, 'Kanamycin Meiji Injeksi', 0, 0, 0, 'Vial', '', 1, 'OTC', 14864.86486, 0, 16500, 0, 21000, 19798, 17325, 0, '', '<p><span style=\"font-family:open sans,arial; font-size:14px\">Untuk infeksi serius yang disebabkan oleh&nbsp;</span><em>Escherichia coli, Klebsiella pneumoniae, Enterobacter aerogenes, Proteus vulgaris</em></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(4142, 6281073210143, 0, 'Alshifa Natural Honey 250 g', 0, 0, 0, 'Botol', '', 1, 'OTC', 0, 0, 37750, 0, 75000, 45296, 39638, 0, '', '<p><span style=\"font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">Meningkatkan stamina tubuh.&nbsp;Membantu kekuatan sistem pencernaan.&nbsp;Menjaga kesehatan hati.&nbsp;Membantu pemulihan pada masa setelah sakit/operasi.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 1, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(4143, 200904, 0, 'Sulfadiazin 500 mg 10 Tablet', 0, 0, 0, 'Strip', '', 1, 'OTC', 7252.3, 0, 7245, 0, 15000, 8693, 7607, 0, '', '<div class=\"tab-desc m-b-30 m-t-20\" style=\"box-sizing: border-box; margin-top: 20px; margin-bottom: 30px; color: rgb(83, 83, 83); font-family: GothamRounded, sans-serif; font-size: 12px;\">\r\n<p>Obat ini digunakan menghilangkan bakteri yang menyebabkan infeksi, dengan cara menghentikan produksi asam folat di dalam sel bakteri.</p>\r\n</div>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 6, '', 'inactive', NULL, 'standar', NULL, ''),
(4144, 200905, 0, 'Atorvastatin 20 mg 10 Tablet Dexa', 0, 0, 0, 'Strip', 'Box', 10, 'OTC', 400000, 0, 14208, 0, 30000, 17048, 14918, 0, '', '<p><span style=\"font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">ATORVASTATIN 20 MG merupakan jenis obat golongan penghambat HMG-CoA reduktase atau disebut statin. Obat ini digunakan sebagai tambahan diet untuk menurunkan peningkatan kolesterol total, kolesterol LDL, apo-B &amp; trigliserida pada pasien dengan hiperkolesterolemia primer, hiperlipidemia kombinasi (campuran) &amp; hiperkolesterolemia familial heterozigot &amp; homozigot bila respons terhadap diet &amp; tindakan nonfarmakologis lainnya tidak adekuat.&nbsp;</span></p>\r\n', '', '', '0000-00-00 00:00:00', 4, 0, 0, 4, '', 'inactive', NULL, 'standar', NULL, ''),
(4145, 8993430169633, 0, 'Egoji Chewy Gummy Jeruk 20 g Isi 10', 0, 0, 0, 'Sach', 'Box', 5, 'OTC', 35000, 0, 7304, 0, 10000, 8764, 7669, 0, '', '<p><strong>Membantu meningkatkan daya tahan tubuh, membantu mempercepat penyembuhan penyakit, mencegah agar tidak mudah terserang penyakit</strong></p>\r\n', '', '', '0000-00-00 00:00:00', 4, 0, 0, 4, '', 'inactive', NULL, 'standar', NULL, ''),
(4146, 8993430174125, 0, 'Egoji Chewy Gummy Blackcurrant 25 g Isi 10', 0, 0, 0, 'Sach', 'Box', 5, 'OTC', 35000, 0, 7304, 0, 10000, 8764, 7669, 0, '', '<p><strong>Membantu meningkatkan daya tahan tubuh, membantu mempercepat penyembuhan penyakit, mencegah agar tidak mudah terserang penyakit</strong></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(4147, 200906, 0, 'Orinox 90 mg 1 Tablet', 0, 0, 0, 'Tablet', 'Box', 30, 'OTC', 285000, 0, 10123, 0, 12000, 12147, 10629, 0, '', '<p><span style=\"background-color:rgb(249, 249, 249); font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">ORINOX 90 MG mengandung obat Etoricoxib adalah obat untuk mengurangi nyeri dan bengkak pada sendi dan otot penderita osteoarthritis, rematik, ankylosing spondylitis, dan asam urat. Etoricoxib juga berguna untuk pengobatan nyeri sedang setelah operasi gigi dalam jangka pendek. Etoricoxib adalah kelompok obat penghambat COX-2 selektif yang termasuk golongan NSAID.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 3, 0, 0, 16, '', 'inactive', NULL, 'standar', NULL, ''),
(4148, 200907, 0, 'Grazeo 10 mg 10 Tablet', 0, 0, 0, 'Strip', 'Box', 1, 'OTC', 16270, 0, 18060, 0, 4000, 21670, 18963, 0, '', '<p><span style=\"color:rgb(25, 34, 42); font-family:blibli,-apple-system,segoe ui,roboto,helvetica,arial,sans-serif; font-size:14px\">Grazeo digunakan sebagai terapi pada rheumatoid artritis, osteoartritis, ankilosa spondilitis, gout akut, dan gangguan muskuloskeletal.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 3, 0, 0, 5, '', 'inactive', NULL, 'standar', NULL, ''),
(4149, 200908, 0, 'Grazeo 20 mg 10 Tablet', 0, 0, 0, 'Strip', 'selected', 1, 'OTC', 2220, 0, 2464, 0, 6000, 2957, 2587, 0, '', '<p><span style=\"color:rgb(25, 34, 42); font-family:blibli,-apple-system,segoe ui,roboto,helvetica,arial,sans-serif; font-size:14px\">Grazeo digunakan sebagai terapi pada rheumatoid artritis, osteoartritis, ankilosa spondilitis, gout akut, dan gangguan muskuloskeletal.</span><br />\r\n&nbsp;</p>\r\n', '', '', '0000-00-00 00:00:00', 5, 0, 0, 6, '', 'inactive', NULL, 'standar', NULL, '');
