(4151, 8995232700571, 0, 'Vitacid 0.025% Gel 20 g ', 0, 0, 0, 'Tube', 'Tube', 1, 'OTC', 25315, 0, 26695, 0, 35000, 32031, 28030, 0, '', '<p><span style=\"font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">VITACID GEL merupakan obat jerawat topikal dengan kandungan Retinoic Acid atau Asam Retinoat (tretinoin). Retinoic Acid meningkatkan mitosis dan pergantian sel epidermal serta menekan sintesis keratin. Permeabilitas kulit meningkat menyebabkan hilangnya cairan sehingga memudahkan pengelupasan kulit dan mencegah terbentuknya pengelupasan kulit. Oleh karena itu, Vitacid Cream efektif digunakan untuk pengobatan jerawat komedogenik, papul, dan pustul.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 6, '', 'inactive', NULL, 'standar', NULL, ''),
(4152, 200910, 0, 'Alvita 10 Kaplet', 0, 0, 0, 'Strip', '', 1, 'OTC', 4597.5, 0, 5103, 0, 13000, 6123, 5358, 0, '', '<p><span style=\"color:rgb(83, 83, 83); font-family:gothamrounded,sans-serif; font-size:12px\">Alvita adalah obat yang digunakan untuk meringankan rasa sakit/nyeri yang berat yang disebabkan oleh neuritis (saraf perifer yang meradang) dan neuralgia (gangguan pada sinyal saraf di sistem saraf).</span></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
