(4177, 200923, 0, 'Hufafural Suspensi 60 ml', 0, 0, 0, 'Botol', 'Botol', 1, 'OTC', 9808, 0, 10887, 0, 20000, 13063, 11431, 0, '', '<p><span style=\"background-color:rgb(249, 249, 249); font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">HUFAFURAL SIRUP adalah obat antibiotik dengan kandungan Nifuroxazid 250 mg/5 ml sirup. Nifuroxazid adalah antibiotik golongan Nitrofuran untuk mengobati infeksi pada saluran cerna yang disebabkan oleh E.Coli atau Staphylococcus. Obat ini merupakan terapi efektif untuk diare akut dan dapat diresepkan untuk diare tak akut tanpa harus menunggu hasil pengecekan feses yang mungkin terlambat atau negatif.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(4178, 200924, 0, 'Eperisone HCl 50 mg 10 Tablet Medikon', 0, 0, 0, 'Blister', 'selected', 1, 'OTC', 15600, 0, 17316, 0, 22000, 20777, 18182, 0, '', '<p><span style=\"font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">Untuk pengobatan simtomatik pada kondisi yang berhubungan dengan spasme muskuloskeletal</span></p>\r\n', '', '', '0000-00-00 00:00:00', 3, 0, 0, 3, '', 'inactive', NULL, 'standar', NULL, ''),
(4179, 8993113686051, 0, 'Comtusi Sirup 60 ml', 0, 0, 0, 'Botol', 'Botol', 1, 'OTC', 38500, 0, 40171, 42735, 53000, 48201, 42180, 0, '', '<p><span style=\"background-color:rgb(249, 249, 249); font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">COMTUSI SIRUP adalah obat yang mengandung Oxememazine dan Guaifenesin. Obat ini digunakan untuk mengatasi batuk akibat alergi serta batuk berdahak. Obat ini merupakan kombinasi oksomemazin yang merupakan antihistamin dan guafenesin yang dapat berfungsi sebagai pengencer dahak.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 6, 0, 0, 6, '', 'inactive', NULL, 'standar', NULL, ''),
