INSERT INTO `barang` (`id_barang`, `kd_barang`, `category_id`, `nm_barang`, `stok_barang`, `stok_buffer`, `stok_grosir`, `sat_barang`, `sat_grosir`, `konversi`, `jenisobat`, `hna`, `diskon`, `hrgsat_barang`, `hrgsat_grosir`, `hrgjual_barang`, `hrgjual_barang1`, `hrgjual_barang2`, `komisi`, `zataktif`, `indikasi`, `ket_barang`, `dosis`, `waktu`, `t30`, `t60`, `gr`, `q30`, `petugas`, `status`, `image`, `promosi`, `tgl`, `updated_by`) VALUES
(4401, 201041, 0, 'Metronidazole 500 mg 10 Tablet Bernofarm', 0, 0, 0, 'Strip', '', 1, 'OTC', 2522.522523, 0, 2800, 0, 5000, 3360, 2940, 0, '', '<p><span style=\"font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">METRONIDAZOLE 500 MG TABLET adalah obat generik antimikroba dengan aktivitas yang sangat baik terhadap bakteri anaerob dan protozoa. Obat ini digunakan untuk mengobati infeksi trichomonas vaginalis, bakterial vaginosis (Infeksi Gardnerella vaginalis) dan infeksi Entamoeba histolytica dan Giardia lamblia (penyakit Giardiasis). Obat ini juga digunakan untuk pembedahan dan sepsis ginekologi dengan aktivitas utama terhadap bakteri anaerob kolon, terutama Bacteroides fragilis.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 3, 0, 0, 3, '', 'inactive', NULL, 'standar', NULL, ''),
(4402, 201042, 0, 'Omeprazole 20 mg 10 Kapsul Ifars', 0, 0, 0, 'Strip', 'Box', 3, 'OTC', 8594, 0, 3180, 0, 7000, 3816, 3339, 0, '', '<p><span style=\"background-color:rgb(249, 249, 249); font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">OMEPRAZOLE merupakan obat golongan proton pump inhibitor (PPI). Obat ini diindikasikan untuk tukak lambung dan tukak duodenum, tukak lambung dan duodenum yang terkait dengan AINS, lesi lambung dan duodenum, regimen eradikasi H. pylori pada tukak peptik, refluks esofagitis, Sindrom Zollinger Ellison.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 2, 0, 0, 2, '', 'inactive', NULL, 'standar', NULL, ''),
(4403, 8996838396014, 0, 'Nellco Bedak Salicyl Genesis Menthol 60 g', 0, 0, 0, 'Botol', 'Botol', 1, 'OTC', 6037, 0, 6701, 0, 8000, 8041, 7036, 0, '', '<p><span style=\"background-color:rgb(249, 249, 249); font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">Nellco digunakan untuk meringankan gatal-gatal pada kulit karena biang keringat. Nellco mengandung Talkum, Menthol, Parfum, dan Asam salisilat.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 1, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(4404, 8996838396021, 0, 'Nellco Bedak Salicyl Cool & Fresh Menthol 60 g', 0, 0, 0, 'Botol', '', 1, 'OTC', 5855.855856, 0, 6660, 0, 8000, 7991, 6993, 0, '', '<p><span style=\"background-color:rgb(249, 249, 249); font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">Nellco digunakan untuk meringankan gatal-gatal pada kulit karena biang keringat. Nellco mengandung Talkum, Menthol, Parfum, dan Asam salisilat.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(4405, 201043, 0, 'Meloxicam 7.5 mg 10 Tablet HJ', 0, 0, 0, 'Strip', 'Box', 10, 'OTC', 48000, 0, 3680, 0, 9000, 4416, 3864, 0, '', '<p><span style=\"font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">Meredakan gejala-gejala arthritis, misalnya peradangan, pembengkakan, serta kaku dan nyeri otot. Contoh penyakit radang persendian yang biasanya ditangani dengan meloxicam adalah osteoartritis (jangka pendek), rheumatoid arthritis, dan ankylosing spondylitis.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 8, 0, 0, 8, '', 'inactive', NULL, 'standar', NULL, ''),
(4406, 8993430174545, 0, 'Iprox Forte Suspensi 60 ml', 0, 0, 0, 'Botol', 'Botol', 1, 'OTC', 32500, 0, 35354, 0, 45000, 42421, 37122, 0, '', '<p><span style=\"color:rgb(0, 0, 0); font-family:poppins\">IPROX SUSP STRAWBERRY 60ML memiliki kandungan bahan aktif Ibuprofen yang efektif mengobati nyeri dengan intensitas rendah sampai sedang, dan efektif terhadap nyeri yang berkaitan dengan inflamasi atau kerusakan jaringan seperti: *Penyakit rematik tulang dan sendi. *Gejala arthritis, osteoarthritis, dan non-sendi. *Gejala-gejala akibat trauma otot dan tulang atau sendi (trauma muskuloskeletal). *Nyeri ringan sampai sedang antara lain nyeri pada dismenore primer (nyeri haid), nyeri pada gigi, sakit kepala. Iprox Susp memiliki mekanisme kerja dengan cara menghambat enzim siklooksigenase sehingga konversi asam arakidonat menjadi terganggu serta menghalangi tubuh memproduksi prostaglandin, yaitu senyawa yang menyebabkan peradangan dan rasa sakit. Obat ini dapat dikonsumsi bersamaan dengan makanan. Konsultasikan terlebih dahulu kepada dokter apabila akan digunakan pada pasien dengan kondisi: *Riwayat alergi terhadap kandungan obat ini. *Penderita riwayat tukak peptik *Gangguan fungsi ginjal *Koagulasi darah *Gagal jantung *Hipertensi *Retensi cairan tubuh *Asma *Lupus eritematosus sistemik *Wanita hamil dan menyusui *Anak usia kurang dari 1 tahun Interaksi dapat terjadi apabila digunakan bersamaan dengan obat-obatan seperti: *Ibuprofen dapat menurunkan efek dari obat golongan ACE inhibitor dan ARB. *Peningkatan risiko luka atau pendarahan pada saluran pencernaan jika digunakan bersama dengan NSAID lain seperti aspirin, antiplatelet, antikoagulan (misalnya warfarin), kortikosteroid serta SSRI.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 2, 0, 0, 2, '', 'inactive', NULL, 'standar', NULL, ''),
(4407, 8992702006003, 0, 'Indomilk Kids Rasa Melon 190 ml', 0, 0, 0, 'Botol', '', 1, 'OTC', 0, 0, 3750, 0, 6000, 4500, 3938, 0, '', '<p><span style=\"font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">Susu UHT Indomilk kaya akan Vitamin D, A, B2, B2, B6, E, Fosfor dan Kalsium yang baik untuk pertumbuhan dan kekebalan tubuh</span></p>\r\n', '', '', '0000-00-00 00:00:00', 13, 0, 0, 15, '', 'inactive', NULL, 'standar', NULL, ''),
(4408, 8995227500278, 0, 'Larutan Cap Kaki Tiga Rasa Leci 320 ml', 0, 0, 0, 'Kaleng', '', 1, 'OTC', 0, 0, 5500, 0, 7000, 6599, 5775, 0, '', '', '', '', '0000-00-00 00:00:00', 0, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(4409, 8992918265027, 0, 'Madu Nusantara 250 ml', 0, 0, 0, 'Botol', '', 1, 'OTC', 0, 0, 74000, 0, 90000, 88793, 77700, 0, '', '<p><span style=\"font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">Madu super adalah madu murni yang diperkaya dengan royal jelly dan bee pollen yang berkhasiat bagi kesehatan Indikasi / Manfaat / Kegunaan : Meningkatkan stamina dan daya tahan tubuh. Meredakan demam, batuk, pilek, sakit kepala, panas dalam, sariawan, bibir pecah-pecah, radang tenggorokan, amandel, menjaga kesehatan kulit, Nutrisi bergizi bagi ibu hamil dan menyusui.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 2, 0, 0, 2, '', 'inactive', NULL, 'standar', NULL, ''),
(4410, 8992918165020, 0, 'Madu Randu Madu Murni Nusantara 250 ml', 0, 0, 0, 'Botol', '', 1, 'OTC', 0, 0, 60200, 0, 75000, 72234, 63210, 0, '', '<p><span style=\"font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">MADU MURNI NUSANTARA adalah madu murni yang diperkaya dengan Royal Jelly dan Bee Pollen. Madu ini berkhasiat untuk membantu melancarkan peredaran darah, mempertahankan stamina tubuh, menghilangkan rasa pegal di badan, membantu pertumbuhan tulang dan gigi, mencegah gejala anemia, serta membantu memperlambat penuaan</span></p>\r\n', '', '', '0000-00-00 00:00:00', 2, 0, 0, 2, '', 'inactive', NULL, 'standar', NULL, ''),
(4411, 201044, 0, 'Ultraproct-N Cream 10 g', 0, 0, 0, 'Tube', 'Tube', 1, 'OTC', 115294, 0, 127336, 127976, 158000, 152790, 133703, 0, '', '<div class=\"drug-list\" style=\"box-sizing: border-box; border-width: 0px; border-style: solid; border-color: currentcolor; --tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-gradient-from-position: ; --tw-gradient-via-position: ; --tw-gradient-to-position: ; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; font-size: 16px; font-weight: 700; color: rgb(83, 86, 90); padding: 0px; font-family: Inter, sans-serif;\">\r\n<div class=\"ttl-list\" style=\"box-sizing: border-box; border-width: 0px; border-style: solid; border-color: currentcolor; --tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-gradient-from-position: ; --tw-gradient-via-position: ; --tw-gradient-to-position: ; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ;\"><span style=\"font-size:14px\">ULTRAPROCT-N CREAM merupakan obat anorektal atau yang digunakan dengan cara dimasukkan ke anus untuk mengobati wasir/ambeien, peradangan atau perlukaan di bagian dalam anus. Ultraproct mengandung fluocortolone dan lidocaine. Fluocortolone adalah merupakan senyawa obat dari golongan glukokortikoid yang memiliki kemampuan anti-inflamasi kuat. lidocaine merupakan senyawa obat anastesi lokal yang bekerja dengan cara menstabilkan membran saraf dan menghambat fluks ionik yang diperlukan dalam konduksi impuls sehingga rangasangannya dapat diputus.</span></div>\r\n</div>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 6, '', 'inactive', NULL, 'standar', NULL, ''),
