(4447, 201060, 0, 'Otsu D5 Dextrose Monohydrate 500 ml Soft Bag', 0, 0, 0, 'Fls', 'Fls', 1, 'OTC', 7685, 0, 8530, 0, 12000, 10235, 8957, 0, '', '<p><span style=\"background-color:rgb(249, 249, 249); font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">Dextrose adalah&nbsp;obat yang berguna untuk membantu memenuhi kebutuhan gula dalam tubuh. Obat ini dikonsumsi oleh pengidap kadar gula darah rendah atau hipoglikemia.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(4448, 201061, 0, 'Otsu D10 Dextrose Monohydrate 10% 500 ml', 0, 0, 0, 'Botol', 'Fls', 1, 'OTC', 8991, 0, 9980, 11090, 15000, 11975, 10479, 0, '', '<p><span style=\"background-color:rgb(249, 249, 249); font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">Dextrose adalah&nbsp;obat yang berguna untuk membantu memenuhi kebutuhan gula dalam tubuh. Obat ini dikonsumsi oleh pengidap kadar gula darah rendah atau hipoglikemia.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 2, 0, 0, 2, '', 'inactive', NULL, 'standar', NULL, ''),
(4449, 8994805021396, 0, 'Cefadroxil 125 mg/5 ml Sirup Kering 60 ml HJ', 0, 0, 0, 'Botol', 'selected', 1, 'OTC', 10000, 0, 11100, 0, 17000, 13319, 11655, 0, '', '<p><span style=\"background-color:rgb(249, 249, 249); font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">CEFADROXIL SIRUP KERING merupakan antibiotika golongan Cefalosporin. Antibiotika ini bekerja dengan cara mengikat 1 atau lebih protein pengikat penisilin (PBPs) yang pada gilirannya menghalangi langkah transpeptidasi akhir sintesis peptidoglikan di dinding sel bakteri, sehingga menghambat biosintesis dinding sel dan menahan perakitan dinding sel yang mengakibatkan lisis bakteri. Antibiotik ini digunakan untuk mengatasi infeksi saluran pernafasan, saluran kemih dan kelamin serta infeksi kulit dan jaringan lunak.&nbsp;</span></p>\r\n', '', '', '0000-00-00 00:00:00', 1, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(4450, 8995201801155, 0, 'Counterpain Cool Gel 120 g', 0, 0, 0, 'Tube', 'Tube', 1, 'OTC', 90000, 0, 99900, 0, 122000, 119870, 104895, 0, '', '<p><strong>COUNTERPAIN COOL</strong><span style=\"background-color:rgb(249, 249, 249); font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">&nbsp;GEL merupakan sediaan bentuk gel yang digunakan untuk meredakan nyeri otot dan nyeri sendi seperti nyeri saat terkilir, pegal-pegal atau cedera pada saat olahraga serta memar dengan sensasi dingin.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(4451, 8991102020459, 0, 'Sikat Gigi Formula Trendy 1 pcs', 0, 0, 0, 'Pcs', '', 1, 'OTC', 2432.416667, 0, 2700, 0, 5000, 3240, 2835, 0, '', '', '', '', '0000-00-00 00:00:00', 1, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(4452, 8995201801629, 0, 'Tempra Forte Sirup Rasa Anggur 30 ml', 0, 0, 0, 'Botol', 'Botol', 1, 'OTC', 22500, 0, 24975, 0, 32000, 29968, 26224, 0, '', '<p><span style=\"background-color:rgb(249, 249, 249); font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">TEMPRA FORTE merupakan obat penurun demam yang mengandung Paracetamol 250 mg tiap 5 ml sirup. Paracetamol bekerja sebagai antipiretik pada pusat pengaturan suhu di otak dan analgetika dengan meningkatkan ambang rasa sakit. Obat ini dapat digunakan untuk menurunkan demam, rasa sakit dan nyeri ringan, sakit kepala dan sakit gigi, demam setelah imunisasi.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 4, 0, 0, 4, '', 'inactive', NULL, 'standar', NULL, ''),
