(4458, 201065, 0, 'Calcium Lactate 500 mg 10 Tablet Nova', 0, 0, 0, 'Strip', '', 1, 'OTC', 1147, 0, 1273, 0, 3500, 1528, 1337, 0, '', '<p><span style=\"font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">CALCIUM LACTATE merupakan obat yang digunakan untuk pengobatan kekurangan kalsium, serta memelihara kesehatan tulang dan gigi.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(4459, 201066, 0, 'Zelona Gel 20 g', 0, 0, 0, 'Tube', '', 1, 'OTC', 6750, 0, 7492, 0, 20000, 8990, 7867, 0, '', '<p><span style=\"color:rgb(0, 0, 0); font-family:poppins; font-size:14px\">ZELONA EMULGEL 20G memiliki kandungan bahan aktif Diklofenak dietilamin yang digunakan untuk mengobati peradangan akibat trauma tendon, ligamenta, otot dan sendi, misalnya: terkilir, keseleo dan memar.</span><br />\r\n&nbsp;</p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 6, '', 'inactive', NULL, 'standar', NULL, '');
