(4640, 201133, 0, 'Mecobalamin 500 mcg 10 Kapsul Novell', 0, 0, 0, 'Blister', 'Box', 10, 'OTC', 90000, 0, 8492, 0, 13000, 10190, 8917, 0, '', '<p><span style=\"font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">MECOBALAMIN 500 MCG KAPSUL adalah obat generik yang merupakan satu bentuk kimiawi-nya berupa co-enzyme dari B12. Obat ini digunakan untuk&nbsp;</span><strong>mengobati neuropati perifer (saraf tepi) dan anemia megaloblastik yang disebabkan oleh defisiensi vitamin B12</strong><span style=\"font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 3, 0, 0, 4, '', 'inactive', NULL, 'standar', NULL, ''),
(4641, 8999809104731, 0, 'Imunped Sirup 120 ml', 0, 0, 0, 'Botol', 'Botol', 1, 'OTC', 75000, 0, 81585, 0, 100000, 97894, 85664, 0, '', '<p><span style=\"font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">IMUNPED SIRUP merupakan suplemen makanan yang mengandung vitamin c dan zinc sulfat. Suplemen ini digunakan sebagai suplementasi zinc dan vitamin c pada anak-anak.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
