(4694, 201164, 0, 'Metformin 500 mg 10 Tablet Dexa', 0, 0, 0, 'Strip', '', 1, 'OTC', 1815, 0, 2015, 0, 3000, 2418, 2116, 0, '', '<p><span style=\"background-color:rgb(249, 249, 249); font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">Terapi awal untuk diabetes dewasa dengan keadaan kelebihan berat badan serta kadar gula darah yang tidak dapat dikendalikan hanya dengan diet saja. Terapi kombinasi untuk kegagalan terapi Sulfonilurea primer atau sekunder. Terapi tambahan pada insulin-dependent diabetes mellitus (IDDM) atau diabetes tipe 1 untuk mengurangi dosis insulin. Metformin HCl 500 mg</span></p>\r\n', '', '', '0000-00-00 00:00:00', 2, 0, 0, 3, '', 'inactive', NULL, 'standar', NULL, ''),
(4696, 201166, 0, 'Beneuron 10 Tablet', 0, 0, 0, 'Strip', 'Box', 10, 'OTC', 70000, 0, 4390, 0, 10000, 5268, 4610, 0, '', '<p>BENEURON 10 TABLET mengandung vitamin B1, B6 dan B12. Obat ini digunakan untuk mengatasi gangguan saraf tepi dan kekurangan vitamin B</p>\r\n\r\n<p>&nbsp;</p>\r\n', '', '', '0000-00-00 00:00:00', 1, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
