(4979, 201306, 0, 'Terumo Disposable Syringe Spuit 10 ml', 0, 0, 0, 'Pcs', 'Pcs', 1, 'OTC', 0, 0, 4000, 4000, 9000, 4800, 4200, 0, '', '<p style=\"text-align:justify\">SPUIT 10 CC merupakan peralatan medis suntik yang digunakan untuk menyuntikkan cairan.</p>\r\n\r\n<p style=\"text-align:justify\">Indikasi Umum</p>\r\n\r\n<p style=\"text-align:justify\">Alat medis suntik yang digunakan untuk menyuntikkan cairan.</p>\r\n', '', '', '0000-00-00 00:00:00', 1, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(4980, 201307, 0, 'Sari Kurma Angkak Madu Propolis Plus Jambu Biji Habbasyifa 470 g', 0, 0, 0, 'Botol', 'Botol', 1, 'OTC', 0, 0, 30000, 30000, 50000, 35997, 31500, 0, '', '<p><span style=\"background-color:rgb(249, 249, 249); font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">merupakan madu yang dikombinasikan dengan sari kurma, angkak, cacing, jambu batu, dan herbal lainnya. Madu ini berkhasiat untuk membantu mengatasi penyakit seperti&nbsp;demam, demam berdarah, thypus, maag, masalah pencernaan, meningkatkan nafsu makan, stamina, serta memelihara daya tahan tubuh.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 4, 0, 0, 4, '', 'inactive', NULL, 'standar', NULL, ''),
