(5015, 201326, 0, 'Ondansetron 4 mg 10 Tablet Dexa', 0, 0, 0, 'Strip', 'Box', 3, 'OTC', 42000, 0, 12121, 46620, 20000, 14544, 12727, 0, '', '<p><strong>ONDANSETRON 4 MG</strong><span style=\"background-color:rgb(249, 249, 249); font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">&nbsp;TABLET merupakan&nbsp;</span><strong>obat</strong><span style=\"background-color:rgb(249, 249, 249); font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">&nbsp;antiemetik yang digunakan untuk meredakan mual dan muntah akibat kemoterapi serta pencegahan mual dan muntah paska operasi.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 8, 0, 0, 9, '', 'inactive', NULL, 'standar', NULL, ''),
(5016, 201327, 0, 'Ondansetron 8 mg 10 Tablet Dexa', 0, 0, 0, 'Strip', 'Box', 3, 'OTC', 69000, 0, 17871, 76590, 30000, 21443, 18765, 0, '', '<p><span style=\"font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">ONDANSETRON merupakan obat antiemetik yang digunakan untuk meredakan mual dan muntah akibat kemoterapi serta pencegahan mual dan muntah paska operasi. Ondansetron bekerja sebagai antagonis reseptor 5-HT3 yang memblok serotonin pada Chemoreceptor Trigger Zone (CTZ). Pemblokan ini menyebabkan efek antiemetik (anti mual dan muntah).&nbsp;</span></p>\r\n', '', '', '0000-00-00 00:00:00', 5, 0, 0, 5, '', 'inactive', NULL, 'standar', NULL, ''),
