(5026, 201329, 0, 'Azithromycin 500 mg 10 Kaplet KF', 0, 0, 0, 'Strip', 'Box', 2, 'OTC', 60739, 0, 33710, 67710, 45000, 40449, 35396, 0, '', '<p><span style=\"background-color:rgb(249, 249, 249); font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">AZITHROMYCIN adalah obat antibiotik generik golongan makrolida yang aktivitasnya terhadap bakteri gram positif dan gram negatif. Obat ini bekerja dengan cara mengikat sub unit 50s dari ribosom bakteri sehingga menghambat translasi mRNA. Dengan demikian sistesis protein akan terganggu sehingga pertumbuhan bakteri akan terhambat. Obat ini digunakan untuk pengobatan infeksi yang disebabkan oleh H. influenzae, M. catarrhalis, S. pneumoniae, C. pneumoniae, H. influenzae, Streptococcus pyogenes, S. aureus, atau S. agalactiae.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 1, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(5027, 201330, 0, 'Erdosteine 300 mg 10 Kapsul Promed', 0, 0, 0, 'Strip', 'Box', 10, 'OTC', 195000, 0, 21645, 216450, 28000, 25972, 22727, 0, '', '<p><span style=\"font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">Eksaserbasi akut bronkitis kronis, Gangguan pernapasan akut yang berhubungan dengan produksi lendir yang berlebihan, Gangguan pernapasan kronis yang berhubungan dengan produksi lendir yang berlebihan</span></p>\r\n', '', '', '0000-00-00 00:00:00', 7, 0, 0, 7, '', 'inactive', NULL, 'standar', NULL, ''),
(5028, 201331, 0, 'Ambroxol 30 mg/5 ml 60 ml Sirup Bernofarm', 0, 0, 0, 'Botol', 'Botol', 1, 'OTC', 9000, 0, 5495, 9990, 13000, 6593, 5770, 0, '', '<p><span style=\"background-color:rgb(249, 249, 249); font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">AMBROXOL SIRUP 30 MG/5 ML adalah agen mukolitik yang bekerja dengan cara meningkatkan sekresi saluran pernapasan dengan meningkatkan produksi surfaktan paru dan merangsang aktivitas silia dan menghasilkan peningkatan pembersihan mukosiliar serta peningkatan sekresi cairan yang memfasilitasi pengeluaran dan meredakan batuk. Obat ini digunakan sebagai sekretolitik pada gangguan saluran nafas akut dan kronis khususnya pada eksaserbasi bronkitis kronis dan bronkitis asmatik dan asma bronkial.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 7, 0, 0, 8, '', 'inactive', NULL, 'standar', NULL, ''),
