(5053, 201338, 0, 'Meloxicam 15 mg 10 Tablet HJ', 0, 0, 0, 'Strip', 'Box', 10, 'OTC', 85000, 0, 4790, 94350, 12000, 5748, 5030, 0, '', '<p><span style=\"background-color:rgb(249, 249, 249); font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">Meredakan gejala-gejala arthritis, misalnya peradangan, pembengkakan, serta kaku dan nyeri otot. Contoh penyakit radang persendian yang biasanya ditangani dengan meloxicam adalah osteoartritis (jangka pendek), rheumatoid arthritis, dan ankylosing spondylitis.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 2, 0, 0, 2, '', 'inactive', NULL, 'standar', NULL, ''),
(5054, 201339, 0, 'Larce 200 mg Ascorbic Acid Injeksi', 0, 0, 0, 'Ampul', 'Box', 5, 'OTC', 50000, 0, 11100, 55500, 15000, 13319, 11655, 0, '', '<p><span style=\"background-color:rgb(249, 249, 249); color:rgb(25, 34, 42); font-family:blibli,-apple-system,segoe ui,roboto,helvetica,arial,sans-serif; font-size:16px\">Mencegah&nbsp;atau&nbsp;mengatasi&nbsp;kadar&nbsp;vitamin&nbsp;C&nbsp;yang&nbsp;rendah&nbsp;dalam&nbsp;tubuh.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 1, 0, 0, 3, '', 'inactive', NULL, 'standar', NULL, ''),
