(5259, 201406, 0, 'Ibuprofen 100 mg/5 ml Sirup 60 ml Sampharindo', 0, 0, 0, 'Botol', 'Botol', 1, 'OTC', 4729.73, 0, 5250, 4659, 12000, 6299, 5513, 0, '', '<p><strong>IBUPROFEN SIRUP merupakan obat yang memiliki sifat analgesik, anti-inflamasi dan antipiretik. Obat ini dapat digunakan untuk Nyeri ringan sampai sedang antara lain nyeri pada penyakit gigi atau pencabutan gigi, nyeri pasca bedah, sakit kepala, gejala artritis reumatoid, gejala osteoartritis, gejala juvenile artritis reumatoid, menurunkan demam pada anak.</strong></p>\r\n', '', '', '0000-00-00 00:00:00', 5, 0, 0, 6, '', 'inactive', NULL, 'standar', NULL, ''),
(5260, 201407, 0, 'Paracetamol infus 1 g/100 mL Ipha', 0, 0, 0, 'Botol', 'Botol', 1, 'OTC', 16100, 0, 17871, 17871, 30000, 21443, 18765, 0, '', '<p><span style=\"background-color:rgb(249, 249, 249); font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">obat golongan non-opioid dengan onset analgesik dan antipiretik yang cepat</span></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, '');
