(5271, 201413, 0, 'Ondansetron 8 mg 10 Tablet Landson', 0, 0, 0, 'Strip', 'Box', 10, 'OTC', 19819.81982, 0, 2200, 22000, 15000, 2640, 2310, 0, '', '<p><strong>ONDANSETRON 8&nbsp;MG</strong><span style=\"background-color:rgb(249, 249, 249); font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">&nbsp;TABLET merupakan&nbsp;</span><strong>obat</strong><span style=\"background-color:rgb(249, 249, 249); font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">&nbsp;antiemetik yang digunakan untuk meredakan mual dan muntah akibat kemoterapi serta pencegahan mual dan muntah paska operasi.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 2, 0, 0, 2, '', 'inactive', NULL, 'standar', NULL, ''),
(5272, 201414, 0, 'Paride M - Plus 1 mg/250 mg 10 Kaplet', 0, 0, 0, 'Blister', 'Box', 3, 'OTC', 83732, 0, 27263, 92943, 38000, 32713, 28626, 0, '', '<p><strong>PARIDE M - PLUS merupakan obat anti diabetes kombinasi yang terdiri dari Metformin (antidiabetes oral golongan biguanid) dan Glimepiride (antidiabetes oral golongan sulfonilurea). Obat ini digunakan untuk pengobatan diabetes mellitus tipe 2. Paride M-Plus digunakan dengan diet dan olahraga, untuk mengobati DM Tipe 2 ketika penggunaan glimepiride atau metformin saja tidak menghasilkan kontrol glikemik yang adekuat. Obat ini juga digunakan sebagai pengganti terapi kombinasi glimepiride dan metformin.</strong></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(5273, 201415, 0, 'Meprovent Cairan Inhalasi 2.5 ml', 0, 0, 0, 'Ampul', 'Box', 10, 'OTC', 80000, 0, 6216, 88800, 10000, 7459, 6527, 0, '', '<p><span style=\"color:rgb(83, 83, 83); font-family:gothamrounded,sans-serif; font-size:12px\">Digunakan untuk pengobatan bronkospasme akibat penyakit penyumbatan paru kronis.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 21, 0, 0, 998, '', 'inactive', NULL, 'standar', NULL, ''),
