(5531, 2014117, 0, 'Amlodipin 5 mg 10 Tablet Bernofarm', 0, 0, 0, 'Blister', 'Box', 10, 'OTC', 104727, 0, 1407, 116247, 5000, 1688, 1477, 0, '', '<p><span style=\"background-color:rgb(249, 249, 249); font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">Amlodipine berfungsi untuk mengatasi tekanan darah berlebih</span></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(5532, 2014118, 0, 'Amlodipin 10 mg 10 Tablet Bernofarm', 0, 0, 0, 'Blister', 'Box', 10, 'OTC', 184727, 0, 2955, 205047, 10000, 3546, 3103, 0, '', '<p><span style=\"background-color:rgb(249, 249, 249); font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">Amlodipine berfungsi untuk mengatasi tekanan darah berlebih</span></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(5533, 2014119, 0, 'Methylprednisolone 8 mg  10 Tablet Bernofarm', 0, 0, 0, 'Blister', 'Box', 10, 'OTC', 63818, 0, 3273, 70838, 8000, 3927, 3437, 0, '', '<p><span style=\"background-color:rgb(249, 249, 249); font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">METHYLPREDNISOLONE 8 MG merupakan obat golongan glukokortikoid turunan prednisolon yang mempunyai efek kerja dengan cara mengikat dan mengaktifkan reseptor glukokortikoid intraseluler, reseptor glukokortikoid yang diaktifkan berikatan dengan daerah promotor DNA (yang dapat mengaktifkan atau menekan transkripsi) dan mengaktifkan faktor transkripsi yang mengakibatkan inaktivasi gen melalui deasetilasi histon. Obat ini diindikasikan untuk keadaan alergi dan mengurangi peradangan atau supresi inflamasi.&nbsp;</span></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(5534, 2014120, 0, 'Simvastatin 10 mg 10 Tablet Bernofarm', 0, 0, 0, 'Blister', 'Box', 10, 'OTC', 55963, 0, 1572, 62119, 5000, 1886, 1651, 0, '', '<p><span style=\"background-color:rgb(249, 249, 249); font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">SIMVASTATIN merupakan obat penurun kolesterol golongan statin. Obat ini bekerja sebagai inhibitor kompetitif pada HMG-CoA reduktase (enzim yang mempercepat proses sistesis kolesterol). Hal ini dapat menurunkan kadar kolesterol total, LDL, trigliserida, dan meningkatkan kadar HDL dalam darah. Komposisi: Simvastatin 10 mg</span></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 0, '', 'inactive', NULL, 'standar', NULL, ''),
(5535, 2014121, 0, 'Etaflusin 10 Kaplet', 0, 0, 0, 'Strip', 'Box', 10, 'OTC', 31531.53, 0, 3500, 35000, 8000, 4200, 3675, 0, '', '', '', '', '0000-00-00 00:00:00', 0, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, ''),
(5536, 2014122, 0, 'Colchicine 0.5 mg 10 Tablet Combiphar', 0, 0, 0, 'Strip', 'Box', 3, 'OTC', 73675, 0, 25897, 81777, 33000, 31074, 27192, 0, '', '<p><strong>COLCHICINE merupakan obat yang digunakan untuk mengobati atau mencegah serangan gout (kadar asam urat tinggi dalam darah). Obat ini juga dapat digunakan untuk mengobati demam Mediterania familial (gangguan bawaan yang menyebabkan radang perut, dada, dan persendian yang menyakitkan dengan demam berulang).</strong></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 1, '', 'inactive', NULL, 'standar', NULL, '');
