(5615, 2014155, 0, 'Hydrocortison Cream 2.5% 5 g Mulia', 0, 0, 0, 'Tube', 'Tube', 1, 'OTC', 4400, 0, 4884, 4884, 8000, 5860, 5128, 0, '', '<p><span style=\"font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">HYDROCORTISON CREAM adalah obat adrenokortikal steroid yang memiliki sifat anti-inflamasi, anti alergi dan anti pruritus pada jaringan kulit. Hydrocortison di gunakan untuk mengobati eksim, inflamasi, kemerahan,serta gatal-gatal pada kulit, beberapa jenis infeksi kulit yang dapat diobati contohnya dermatitis alergi, dermatitis kontak, dermatitis atopi, pruritus anogenital, neurodermatitis.</span></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 0, '', 'inactive', NULL, 'standar', NULL, ''),
(5616, 2014156, 0, 'Hydrocortison Cream 2.5% 5 g FM', 0, 0, 0, 'Tube', 'Tube', 1, 'OTC', 4621.32, 0, 5130, 5130, 8000, 6155, 5387, 0, '', '<p><span style=\"font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">HYDROCORTISON CREAM adalah obat adrenokortikal steroid yang memiliki sifat anti-inflamasi, anti alergi dan anti pruritus pada jaringan kulit. Hydrocortison di gunakan untuk mengobati eksim, inflamasi, kemerahan,serta gatal-gatal pada kulit, beberapa jenis infeksi kulit yang dapat diobati contohnya dermatitis alergi, dermatitis kontak, dermatitis atopi, pruritus anogenital, neurodermatitis. Dalam penggunaan obat ini</span></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 0, '', 'inactive', NULL, 'standar', NULL, ''),
(5617, 2014157, 0, 'Amoxicillin 500  mg 10 Tablet Sampharindo', 0, 0, 0, 'Strip', 'Box', 10, 'OTC', 55516.5, 0, 6162, 61623, 9000, 7394, 6470, 0, '', '<p><span style=\"background-color:rgb(249, 249, 249); font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">Indikasi Umum: Penyakit infeksi kulit dan jaringan lunak, infeksi saluran pernafasan, infeksi saluran genitourinari, dan gonore yang disebabkan organisme Gram positif &amp; Gram Negatif yang peka terhadap Amoxicillin</span></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 0, '', 'inactive', NULL, 'standar', NULL, ''),
